<?php

declare(strict_types=1);

namespace Sabri\CF02\Infrastructure\WordPress;

final class CompleteFrontendScript
{
    public static function render(): string
    {
        return <<<'JS'
<script>(function(){'use strict';const r=document.querySelector('[data-cf02-complete]');if(!r)return;const base=r.dataset.endpoint.replace(/\/$/,''),nonce=r.dataset.nonce,status=r.querySelector('.cf02-status');let cursor=null;const uid=p=>p+':'+crypto.randomUUID();async function api(path,opt={}){const res=await fetch(base+path,{credentials:'same-origin',...opt,headers:{'Content-Type':'application/json','X-WP-Nonce':nonce,...(opt.headers||{})}});let body={};try{body=await res.json()}catch(e){}if(!res.ok)throw new Error(body.message||'Request failed');return body}function n(t,x,c){const e=document.createElement(t);if(x!=null)e.textContent=String(x);if(c)e.className=c;return e}function panel(name){r.querySelectorAll('[data-panel]').forEach(x=>x.hidden=x.dataset.panel!==name);r.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.tab===name?'true':'false'));if(name==='cases')cases(true)}r.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>panel(b.dataset.tab));async function cases(reset){if(reset)cursor=null;const q=new URLSearchParams({limit:'25'});if(cursor)q.set('cursor',cursor);const out=await api('/cases?'+q),v=r.querySelector('[data-view="cases"]');if(reset)v.replaceChildren();cursor=out.next_cursor||null;(out.items||[]).forEach(c=>{const a=n('article',null,'cf02-case');a.append(n('h3',c.safe_subject||c.case_uuid),n('p',c.case_uuid+' — '+c.state+' — '+c.priority));const b=n('button','Open');b.type='button';b.onclick=()=>open(c.case_uuid);a.append(b);v.append(a)});if(cursor){const b=n('button','Load more');b.type='button';b.onclick=()=>cases(false);v.append(b)}if(reset&&!(out.items||[]).length)v.textContent='No cases found.'}async function open(id){const out=await api('/cases/'+encodeURIComponent(id)),v=r.querySelector('[data-view="case"]');v.replaceChildren();const c=out.case||{},box=n('section',null,'cf02-detail');box.append(n('h3',c.safe_subject||id),n('p',id+' — '+c.state+' — '+c.priority));const th=n('div',null,'cf02-thread');(out.messages||[]).forEach(m=>{const a=n('article',null,'cf02-message');a.append(n('strong',m.author_ref==='Support Team'?'Support Team':'Requester'),n('p',m.body||'[Unavailable]'));th.append(a)});box.append(th);const reply=document.createElement('form');reply.className='cf02-form';reply.innerHTML='<label>Reply<textarea name="body" required maxlength="20000"></textarea></label><button>Send reply</button>';reply.onsubmit=async e=>{e.preventDefault();await api('/cases/'+encodeURIComponent(id)+'/messages',{method:'POST',headers:{'Idempotency-Key':uid('reply')},body:JSON.stringify({body:new FormData(reply).get('body'),channel:'web'})});open(id)};box.append(reply);const up=document.createElement('form');up.className='cf02-form';up.innerHTML='<h4>Secure attachment</h4><label>File<input type="file" name="file" required></label><label>Purpose<input name="purpose" value="case_evidence" required></label><label>Privacy<select name="privacy"><option>C3</option><option>C4</option></select></label><label><input type="checkbox" name="consented" required> I consent to this case-specific upload.</label><button>Upload to quarantine</button>';up.onsubmit=async e=>{e.preventDefault();const f=up.elements.file.files[0];if(!f)return;const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer()))).map(x=>x.toString(16).padStart(2,'0')).join('');const o=await api('/cases/'+encodeURIComponent(id)+'/attachments',{method:'POST',headers:{'Idempotency-Key':uid('attachment'),'X-CF02-Purpose':up.elements.purpose.value},body:JSON.stringify({mime_type:f.type||'application/octet-stream',size:f.size,sha256:hash,purpose:up.elements.purpose.value,privacy_class:up.elements.privacy.value,consented:up.elements.consented.checked})});if(o.upload_session?.upload_url){const u=await fetch(o.upload_session.upload_url,{method:'PUT',headers:o.upload_session.headers||{},body:f});if(!u.ok)throw new Error('Quarantine upload failed')}status.textContent='Attachment quarantined; scan pending.'};box.append(up);const actions=n('div',null,'cf02-actions');function act(label,path){const b=n('button',label);b.type='button';b.onclick=async()=>{await api('/cases/'+encodeURIComponent(id)+path,{method:'POST',headers:{'Idempotency-Key':uid(label.toLowerCase()),'If-Match':'"'+Number(c.record_version||1)+'"'},body:JSON.stringify({record_version:Number(c.record_version||1),reason:'requester_action'})});open(id)};actions.append(b)}if(!['closed','withdrawn'].includes(c.state))act('Withdraw','/withdraw');if(['resolved','closed'].includes(c.state))act('Reopen','/reopen');box.append(actions);if(['resolved','closed'].includes(c.state)){const fb=document.createElement('form');fb.className='cf02-form';fb.innerHTML='<h4>Optional feedback</h4><label>Rating<select name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></label><label>Comment<textarea name="comment"></textarea></label><label><input type="checkbox" name="opted_out"> Opt out</label><button>Submit</button>';fb.onsubmit=async e=>{e.preventDefault();const d=new FormData(fb);await api('/cases/'+encodeURIComponent(id)+'/feedback',{method:'POST',body:JSON.stringify({rating:Number(d.get('rating')),comment:String(d.get('comment')||''),opted_out:d.has('opted_out')})});status.textContent='Feedback recorded'};box.append(fb);const ap=document.createElement('form');ap.className='cf02-form';ap.innerHTML='<h4>Submit appeal</h4><label>Decision reference<input name="original_decision_ref" required></label><label>Policy version<input name="policy_version" required></label><label>Grounds<textarea name="grounds" required></textarea></label><label>Evidence references<textarea name="evidence"></textarea></label><button>Submit appeal</button>';ap.onsubmit=async e=>{e.preventDefault();const d=new FormData(ap),evidence=String(d.get('evidence')||'').split(/\n/).map(x=>x.trim()).filter(Boolean),o=await api('/appeals',{method:'POST',headers:{'Idempotency-Key':uid('appeal')},body:JSON.stringify({case_id:id,original_decision_ref:d.get('original_decision_ref'),policy_version:d.get('policy_version'),grounds:d.get('grounds'),evidence_refs:evidence})});status.textContent='Appeal submitted: '+(o.appeal_uuid||o.appeal?.appeal_uuid||'accepted')};box.append(ap)}v.append(box)}r.querySelector('[data-form="case"]').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.currentTarget),p=Object.fromEntries(d.entries());p.diagnostics_consented=d.has('diagnostics_consented');p.locale=document.documentElement.lang||'ur-PK';if(p.object_owner&&p.object_type&&p.object_ref&&p.object_version){p.affected_object={owner:p.object_owner,type:p.object_type,ref:p.object_ref,version:p.object_version,privacy_class:'C2',safe_projection:{}}}delete p.object_owner;delete p.object_type;delete p.object_ref;delete p.object_version;const o=await api('/cases',{method:'POST',headers:{'Idempotency-Key':uid('intake')},body:JSON.stringify(p)});status.textContent='Case accepted: '+o.case.case_uuid;e.currentTarget.reset();panel('cases')};r.querySelector('[data-action="cases"]').onclick=()=>cases(true);r.querySelector('[data-form="appeal-load"]').onsubmit=async e=>{e.preventDefault();const id=new FormData(e.currentTarget).get('id'),o=await api('/appeals/'+encodeURIComponent(String(id))),a=n('article',null,'cf02-appeal'),v=o.appeal||o;a.append(n('h3',v.appeal_uuid||String(id)),n('p',(v.state||'unknown')+' — '+(v.outcome||'pending')),n('p',v.reasoned_summary||v.further_rights||'Status available.'));r.querySelector('[data-view="appeal"]').replaceChildren(a)};if(r.dataset.initialCase){panel('cases');open(r.dataset.initialCase).catch(e=>status.textContent=e.message)}else if(r.dataset.initialAppeal){panel('appeals');const f=r.querySelector('[data-form="appeal-load"]');f.elements.id.value=r.dataset.initialAppeal;f.requestSubmit()}else{panel('new')}})();</script>
JS;
    }
}
